import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"51、【震】 震下震上","description":"子夏易傳 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"子夏易傳 - 51、【震】 震下震上"},"headers":[],"relativePath":"classics/zixia/053.md","filePath":"classics/zixia/053.md"}'),i={name:"classics/zixia/053.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><p>卦辭：震，亨，震來虩虩，笑言啞啞，震驚百里，不喪匕鬯。</p><p>彖曰：震，亨。震來虩虩，恐致福也。笑言啞啞，後有則也。震驚百里，驚逺而懼邇也。出可以守宗廟社稷，以為祭主也。</p><p>子夏：震，亨。因其震而自震也。微而震之，保其終也。雷者天之震也。君子變其容，號令者，上之震也，保其終也。雷來類震者，外一動也。君子省諸內，見外猶驚之，況於自動乎。動者吉，兇悔，吝之所生也。事之來驚，而虩虩然，後獲其笑語也，福之生後之則也。震始生之，陽長子者也。長者能震，是震其初也。有其長子，則能驚其逺而懼邇也。君子可以守宗廟祭祀，則匕鬯不缺而保其社稷也。皆初震而有其後者也。</p><p>象曰：洊雷震，君子以恐懼，修省。</p><p>子夏：重雷震而不已也。君子修已而履省之，恐懼之至，患無由及也。</p><p>初九，震來虩虩，後笑言啞啞。吉。</p><p>象曰：震來虩虩，恐致福也。笑言啞啞，後有則也。</p><p>子夏：剛能制斷，辨物也。動之於初，震其始恐懼其初，後有則，得震之義也。</p><p>六二，震來厲，億喪貝，躋於九陵，勿逐，七日得。</p><p>象曰：震來厲，乘剛也。</p><p>子夏：剛初而震之，保其吉也。二而已震，失其義也。乘剛震位，危喪資也。則度其喪而上升矣，兩震不相應也。何所來乎，雖懼而不失中，可以自省，終固其所，勿逐之矣。七日而得其所喪也。七日者，極六爻而反下也。剛斯易矣。</p><p>六三，震蘇蘇，震行無眚。</p><p>象曰：震蘇蘇，位不當也。</p><p>子夏：弱而無當，蘇蘇也。居不安矣。行乃無眚也。</p><p>九四，震遂泥。</p><p>象曰：震遂泥，未光也。</p><p>子夏：光可震也。而屈於柔，安於眾陰之中，已泥者也。失其震首，省不能致後之福，雖得所奉，豈足光哉。</p><p>六五，震往來厲，億無?。有事。</p><p>象曰：震往來厲，危行也。</p><p>子夏：其事在中，大無喪也。懼而往也。尊行何安，其反來也。剛以為疾，故皆危也。則以度而居矣，位得大中，事之主也。剛從而依，而不敢遂逼矣，懐懼而已，無所喪也。</p><p>上六，震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。</p><p>象曰：震索索，中未得也。雖兇無咎，畏鄰戒也。</p><p>子夏：索索而驚，矍矍而視，重震之極而中心不自得也。君子安其身而後動也。極懼也，何所容哉。內外震懼，身之危，徵之兇矣。震不以躬，懼鄰而驚，則無咎也。兩震者，動而自省，則行之有終，陽之和，象之純故也。自震而戒，則可兩震求合，則乖也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
